@using sv_db61015f5ba6478889e789ff8e67eeaa.Services
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeAsync();
        }
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyThemeAsync();
            StateHasChanged();
        });
    }

    private async Task ApplyThemeAsync()
    {
        var dataTheme = ThemeService.Theme switch
        {
            ThemeMode.Light => "light",
            ThemeMode.Dark => "dark",
            _ => "system"
        };

        await JS.InvokeVoidAsync("eval", $"""
            document.documentElement.setAttribute('data-theme', '{dataTheme}');
            document.documentElement.style.setProperty('--accent-color', '{ThemeService.AccentColor}');
        """);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

